-- PT111-S1-Q7. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT111-S1-Q7$batch09$ AND q.stimulus=$batch09$Due to wider commercial availability of audio recordings of authors reading their own books, sales of printed books have dropped significantly.$batch09$ AND q.prompt=$batch09$Which one of the following conforms most closely to the principle illustrated above?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT111-S1-Q7$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT111-S1-Q7$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$Audio recordings of authors reading their own books became more widely available, and sales of printed books dropped significantly.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$An audiobook does the same job as a printed book: you get the book. So the principle is substitution. When a new substitute becomes widely available, people buy less of the product it replaces.$batch09$), (2, $batch09$Goal$batch09$, $batch09$A new substitute arrives, and consumption of the existing product falls.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT111-S1-Q7$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Farmers did switch to machines. But the cause is that labor got more expensive. In the stimulus, nothing happened to the old product. A substitute just became easier to get.$batch09$), ($batch09$B$batch09$, $batch09$New games boost sales of screens. Those products work together, and sales rise. The stimulus has a substitute pulling sales down.$batch09$), ($batch09$C$batch09$, $batch09$A new soft drink enters the market, and people drink less of the established brand. A new substitute arrives, and the old product sells less. Same pattern.$batch09$), ($batch09$D$batch09$, $batch09$A rule forbids playing, and the child focuses on homework. That's a restriction, not a substitute becoming available.$batch09$), ($batch09$E$batch09$, $batch09$Neither program dominates because neither has every feature. No new substitute arrives, and no sales fall.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT111-S1-Q7$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
